"""test-remake6.py -- the page test for the seventh stage of the remake (out27/remake7.py: what the referee's reading found), for
the referee's four broken copies that passed, and for what the first whole pass of planted faults showed the test could not see
(out27/first-pass.kept.out).  tools/shot-gasket.js is changed in place, from out27/shot-gasket.stage6.js.txt to
out27/shot-gasket.stage7.js.txt, and copied to ~/web, where it is run.     python -I out27/test-remake6.py
The page's unchanging words are pinned in tools/pinned-words.json (made by out27/pin-words.js from the page, and read by eye)."""
import os, shutil, re
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); T = os.path.join(HERE, 'tools', 'shot-gasket.js')
def rep(s, a, b, n=1):
    assert s.count(a) == n, (s.count(a), a[:100]); return s.replace(a, b)
def main():
    s = open(T, encoding='utf-8').read()
