    # ---------------------------------------------------------------- helpers, near the top
    s = rep(s, "  const SEVEN =", "  const PIN = JSON.parse(fs.readFileSync(path.join(path.dirname(path.resolve(process.argv[4])), 'tools', 'pinned-words.json'), 'utf8'));      /* the page's unchanging words, as they were read */\n"
               "  // a look in the third panel says first that it is looking; the test waits for the answer, however long the machine takes\n"
               "  const tryLook = async pg => { await pg.click('#try'); await pg.waitForFunction(() => !/^Looking/.test(document.getElementById('tsay').textContent)); await pg.waitForTimeout(50); };\n"
               "  // which circles of a drawn list have anything in the picture, by this test's own geometry: a circle of the gasket if its disc meets the picture, the circle round the rest if its edge does.\n"
               "  // tight is true when some circle is within a hundredth of a pixel of the line between the two, where this test and the page might fairly differ\n"
               "  const inPicture = (st, lit) => { let n = 0, l = 0, tight = false; const W2 = st.size.W / 2, H2 = st.size.H / 2; for (const c of st.drawn) { const b = c[0]; if (b === 0) continue; const r = st.view.s / Math.abs(b), dx = Math.abs((c[1] / b + 2 * c[3] - st.view.cx) * st.view.s), dy = Math.abs((c[2] / b - st.view.cy) * st.view.s);\n"
               "    const d = b < 0 ? Math.hypot(dx + W2, dy + H2) - r : r - Math.hypot(Math.max(dx - W2, 0), Math.max(dy - H2, 0)); if (Math.abs(d) < 0.01) tight = true; if (d >= 0) { n++; if (b > 0 && lit(b)) l++; } } return [n, l, tight]; };\n"
               "  const saidCount = t => { const m = /: ([\\d,]+) circles? drawn(?:, ([\\d,]+) of them)?/.exec(t); return m ? [+m[1].replace(/,/g, ''), m[2] === undefined ? -1 : +m[2].replace(/,/g, '')] : [-1, -1]; };\n"
               "  const SEVEN =")
