               "    const W2 = stT.size.W / 2, H2 = stT.size.H / 2, vis = stT.drawn.filter(c => c[0] > 0 && stT.view.s / c[0] - Math.hypot(Math.max(Math.abs((c[1] / c[0] + 2 * c[3] - stT.view.cx) * stT.view.s) - W2, 0), Math.max(Math.abs((c[2] / c[0] - stT.view.cy) * stT.view.s) - H2, 0)) >= 0).map(c => c[0]).sort((a, c) => a - c).slice(0, 40);\n"
