               "    await fresh.selectOption('#pack', '3'); await fresh.waitForTimeout(250); const ss = await F.state(), far = ss.drawn.filter(c => c[0] > 0 && c[3] !== 0 && ss.view.s / c[0] >= 14 && Math.abs((c[1] / c[0] + 2 * c[3] - ss.view.cx) * ss.view.s) < ss.size.W / 2 - 20 && Math.abs((c[2] / c[0] - ss.view.cy) * ss.view.s) < ss.size.H / 2 - 20).sort((a, c) => a[0] - c[0])[0], qf = far && [ss.box[0] + ss.box[2] / ss.size.W * (ss.size.W / 2 + (far[1] / far[0] + 2 * far[3] - ss.view.cx) * ss.view.s), ss.box[1] + ss.box[3] / ss.size.H * (ss.size.H / 2 - (far[2] / far[0] - ss.view.cy) * ss.view.s)];\n"
               "    await fresh.mouse.click(qf[0], qf[1]); await fresh.waitForTimeout(200); const chf = (await F.state()).chosen, linef = await F.text('#gpick'); await fresh.selectOption('#pack', '1'); await fresh.waitForTimeout(250);\n"
               "    must(far && far[3] !== 0 && chf && chf.join() === far.join() && linef.startsWith('The circle marked ' + grp(far[0]) + ':'), 'in the strip a circle that stands in a later period (' + (far && far[3]) + ' along) can be chosen, and it is that circle that is chosen and named, not its twin in the first period', JSON.stringify([far, chf]) + ' | ' + linef.slice(0, 40));\n"
